CREATE DEFINER=`root`@`localhost` TRIGGER `trg_buyer_orders_before_update` BEFORE UPDATE ON `tb_buyer_orders` FOR EACH ROW BEGIN
    
    SET NEW.last_update = NOW();
    
    
    IF OLD.fulfillment_status IN ('Delivered', 'Canceled', 'Returned') 
       AND (NEW.subtotal <> OLD.subtotal OR NEW.shipping_cost <> OLD.shipping_cost) THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'No se pueden modificar los montos de una orden finalizada o cancelada.';
    END IF;
END ;

