CREATE DEFINER=`root`@`localhost` TRIGGER `trg_buyer_orders_after_update` AFTER UPDATE ON `tb_buyer_orders` FOR EACH ROW BEGIN
    IF OLD.fulfillment_status <> NEW.fulfillment_status THEN
        SET @last_buyer_order_action = CONCAT('Orden ID ', NEW.ID, ' cambió de estado: ', OLD.fulfillment_status, ' -> ', NEW.fulfillment_status);
    END IF;
END ;

